import subprocess
import os
import json
from datetime import datetime

def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    if not os.path.isfile(script_name):
        raise FileNotFoundError(f"Script file '{script_name}' does not exist.")

    start_time = datetime.now()

    try:
        script_path = os.path.abspath(script_name)
        process = subprocess.run(["/bin/sh", script_path])
    except Exception as e:
        raise RuntimeError(f"Error executing the script: {e}")

    end_time = datetime.now()

    log_data = {
        'start_time': start_time.strftime('%Y-%m-%d %H:%M:%S'),
        'end_time': end_time.strftime('%Y-%m-%d %H:%M:%S'),
        'exit_status': process.returncode
    }

    log_dir = os.path.dirname(log_file)
    if log_dir:
        os.makedirs(log_dir, exist_ok=True)

    with open(log_file, 'w') as f:
        json.dump(log_data, f, indent=4)

    return log_data
